/// Create a new schematic evaluator job
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `job` - The description of the job to create
///
/// Returns
/// * The ID of the newly created job
pub async fn create_job(
    ctx: &dyn RequestContext,
    job: RunSpec,
) -> Result<ObjectId, Error> {
    let path = "/v1/api/ulv2/schematicevaluator/jobs";
    let body = Bytes::from(Vec::<u8>::from(job));
    let res = ctx.post(&path, body, "application/octet-stream", None, None).await?;
    res.as_slice().try_into().map_err(Error::from)
}

/// Fetch the details of the job with the given ID. By default this will block until the job is complete.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `id` - The ID of the job to fetch
/// * `timeout` - Timeout in milliseconds to wait before returning a response
///
/// Returns
/// * The details of the job
pub async fn get_job(
    ctx: &dyn RequestContext,
    id: Uuid,
    timeout: Option<i64>,
) -> Result<Job, Error> {
    let path = "/v1/api/ulv2/schematicevaluator/jobs/:id"
        .replace(":id", &id.to_string());
    let mut params = ParamMap::new();
    if let Some(val) = timeout { 
        params.insert("timeout".to_owned(), val.to_string());
    }

    let res = ctx.get(&path, Some(params), None).await?;
    res.as_slice().try_into().map_err(Error::from)
}

/// Fetch the details of the task with the given ID.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `id` - The ID of the task to fetch
///
/// Returns
/// * The details of the task
pub async fn get_task(
    ctx: &dyn RequestContext,
    id: Uuid,
) -> Result<Task, Error> {
    let path = "/v1/api/ulv2/schematicevaluator/tasks/:id"
        .replace(":id", &id.to_string());
    let res = ctx.get(&path, None, None).await?;
    res.as_slice().try_into().map_err(Error::from)
}


